/**
 * The right answers for the AI evaluation. Each label says what is really on a
 * synthetic prescription in frontend/public/samples (generated by
 * scripts/generate-samples.cjs), plus up to three hand-written photos.
 */
export interface ExpectedLine {
  /** What's written on the paper, split the way a perfect reader would. */
  name: string;
  strength: string;
  dose: string;
  duration: string;
  /** The catalog product this line should match. */
  sku: string;
}

export interface EvalLabel {
  file: string;
  /** rx = should be read; blurry and not_rx must never come back as a confident read. */
  kind: 'typed' | 'handwriting_font' | 'handwritten_photo' | 'blurry' | 'not_rx';
  prescriber?: string;
  patient?: string;
  lines: ExpectedLine[];
}

const line = (name: string, strength: string, dose: string, duration: string, sku: string): ExpectedLine => ({ name, strength, dose, duration, sku });

